WITH base AS (SELECT member_id, CAST(date_trunc('month', ordered_at) AS DATE) AS month_start, COUNT(DISTINCT CASE WHEN status = 'paid' AND paid_cents - refund_cents > 0 THEN order_id END) AS valid_order_count FROM {{ ref('orders') }} GROUP BY member_id, CAST(date_trunc('month', ordered_at) AS DATE)) SELECT member_id, month_start, valid_order_count, member_id || '|' || CAST(month_start AS VARCHAR) AS member_month_id FROM base WHERE valid_order_count > 0